// ============================================================================
// [비하인드 내용 자동 보강 엔진] (요청사항 14번 & 9번 완벽 반영)
// - 모든 문제의 비하인드 지문에 발매 시기·장르·결정적 추리 단서를 보강하여
//   힌트 버튼을 누르지 않고 지문만 읽어도 충분히 유추할 수 있도록 자동 강화!
// - 코요태, 쿨, 버즈, SG워너비, 티아라, 다비치, 아이유, 빅뱅, 소녀시대 등
//   다작/혼성/보컬 대표 가수들의 문제를 '하드모드(hardMode)' 풀로 자동 지정!
// ============================================================================
const HARD_MODE_ARTISTS = new Set([
  "코요태", "쿨", "버즈", "SG워너비", "티아라", "다비치", "씨야", "룰라",
  "터보", "샵", "영턱스클럽", "R.ef", "노이즈", "엠씨더맥스", "브라운 아이즈",
  "브라운아이드소울", "플라이 투 더 스카이", "아이유", "빅뱅", "소녀시대",
  "데이식스", "뉴진스", "에스파", "비스트", "인피니트", "에이핑크", "여자친구"
]);

QUESTIONS_DB.forEach(q => {
  if (HARD_MODE_ARTISTS.has(q.artist)) {
    q.hardMode = true;
  }
  if (q.keywordHint) {
    q.keywordHint = sanitizeKeywordHint(q.keywordHint, q, {
      maskArtist: true,
      maskTitle: false
    });
  }
  // 비하인드 지문에 힌트를 누르지 않아도 유추할 수 있는 결정적 배경 단서 보강
  if (q.behindQuestion && !q.behindQuestion.includes("결정적 단서") && !q.behindQuestion.includes("시대 및 추리 단서")) {
    const cleanLyricClue = (q.lyricsQuestion || "").split("/")[0].trim();
    const firstKeyClue = (q.keywordHint || "").split(",")[0].trim();
    q.behindQuestion = `${q.behindQuestion} (💡 시대 및 추리 단서: ${q.year}년에 발매된 곡으로, '${firstKeyClue}' 등의 특징으로 유명하며 "${cleanLyricClue}..." 같은 가사 정서를 담고 있습니다.)`;
  }
  if (q.behindQuestion) {
    q.behindQuestion = maskAnswerInBehindText(
      q.behindQuestion,
      q.artist,
      q.artistAliases,
      q.title,
      q.titleAliases
    );
  }
});

// ============================================================================
// [공용 유틸] 정답 정규화 · 빈칸/글자수 계산 · MD 문제 파서 & 정답 마스킹
// (index.html / admin.html 양쪽에서 공통으로 재사용)
// ============================================================================
function normalizeQuizText(str) {
  if (!str) return "";
  return str
    .toString()
    .toLowerCase()
    .replace(/[\s\.\,\!\?\-\_\~\'\"\(\)\[\]\{\}\:\;\/\\&]/g, "");
}

function buildQuizLetterHint(text) {
  const trimmed = String(text || "").trim();
  const boxes = Array.from(trimmed)
    .map(ch => (ch === " " ? " " : "□"))
    .join("");
  const charCount = trimmed.replace(/\s+/g, "").length;
  return `${boxes}(${charCount}자)`;
}

function inferDecadeFromYear(year) {
  const y = Number(year) || 2020;
  if (y < 2000) return "1990s";
  if (y < 2010) return "2000s";
  if (y < 2020) return "2010s";
  return "2020s";
}

function escapeQuizRegex(str) {
  return String(str).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function _maskTermsInQuizText(rawText, entries) {
  let result = String(rawText || "").trim();
  if (!result || !Array.isArray(entries) || entries.length === 0) return result;

  // 긴 단어부터 우선 치환하여 부분 문자열 훼손 방지
  const sorted = [...entries].sort((a, b) => b.term.length - a.term.length);

  for (const { term, label } of sorted) {
    const clean = String(term || "").trim();
    if (!clean) continue;
    const isAscii = /^[A-Za-z0-9.\s'&-]+$/.test(clean);
    if (isAscii) {
      const escaped = escapeQuizRegex(clean);
      const re = new RegExp(`(^|[^A-Za-z0-9])${escaped}(?=$|[^A-Za-z0-9])`, "gi");
      result = result.replace(re, `$1${label}`);
    } else if (clean.length === 1) {
      // 1글자 한글 가수·곡명('비', '쿨', '빛' 등)은 조사 앞뒤·단독 표기인 경우에만 조심스럽게 마스킹
      const escaped = escapeQuizRegex(clean);
      const re = new RegExp(`(^|[\\s'"\\[(,])${escaped}(?=$|[\\s'"\\]),.!?;:/]|이|가|의|는|은|을|를|과|와)`, "g");
      result = result.replace(re, `$1${label}`);
    } else {
      // 한국어 띄어쓰기 차이(예: 브라운 아이즈 vs 브라운아이즈) 모두 마스킹
      const pattern = clean.split(/\s+/).map(escapeQuizRegex).join("\\s*");
      const re = new RegExp(pattern, "g");
      result = result.replace(re, label);
    }
  }
  return result;
}

// 비하인드 지문 속 정답(가수명·노래명·동의어)을 [이 가수] / [이 곡] 으로 자동 마스킹
function maskAnswerInBehindText(behindText, artist, artistAliases = [], title, titleAliases = []) {
  const entries = [];
  const pushTerms = (terms, label) => {
    (terms || []).forEach(raw => {
      const t = String(raw || "").trim();
      if (t) entries.push({ term: t, label });
    });
  };
  pushTerms([title, ...(titleAliases || [])], "[이 곡]");
  pushTerms([artist, ...(artistAliases || [])], "[이 가수]");
  return _maskTermsInQuizText(behindText, entries);
}

// 포인트 단어 힌트 내 정답(가수·곡명·별칭) 동적 마스킹
function sanitizeKeywordHint(hintText, q, options = {}) {
  const { maskArtist = true, maskTitle = false } = options;
  if (!hintText || !q) return String(hintText || "").trim();
  const entries = [];
  const pushTerms = (terms, label) => {
    (terms || []).forEach(raw => {
      const t = String(raw || "").trim();
      if (t) entries.push({ term: t, label });
    });
  };
  if (maskTitle) {
    pushTerms([q.title, ...(q.titleAliases || [])], "[이 곡]");
  }
  if (maskArtist) {
    pushTerms([q.artist, ...(q.artistAliases || [])], "[이 가수]");
  }
  return _maskTermsInQuizText(hintText, entries);
}

function parseMarkdownQuestions(mdText) {
  let cleaned = String(mdText || "").replace(/\r\n/g, "\n").trim();
  // 문서 내 코드펜스(```markdown / ```) 라인 제거
  cleaned = cleaned.replace(/^\s*```[A-Za-z0-9_-]*\s*$/gm, "").trim();

  const rawBlocks = cleaned
    .split(/\n\s*---+\s*\n|\n---\s*$/)
    .map(b => b.trim())
    .filter(Boolean);

  // 만약 사용자가 '---' 없이 빈 줄로만 여러 가수 블록을 적었으면 '가수:' 시작 기준으로 추가 분할
  const blocks = [];
  rawBlocks.forEach(block => {
    const subParts = block.split(/\n(?=\s*(?:[-*]\s*)?(?:\*\*)?(?:가수|아티스트)(?:\*\*)?\s*:)/g);
    subParts.forEach(sp => {
      if (sp.trim()) blocks.push(sp.trim());
    });
  });

  const existingMap = new Map();
  QUESTIONS_DB.forEach(q => {
    const k = `${normalizeQuizText(q.artist)}__${normalizeQuizText(q.title)}`;
    if (!existingMap.has(k)) existingMap.set(k, q);
  });

  const parsed = [];
  blocks.forEach((block, idx) => {
    const fields = {};
    let currentKey = null;

    block.split("\n").forEach(rawLine => {
      const line = rawLine.trim();
      if (!line || line.startsWith("#") || line.startsWith(">")) return;

      const m = line.match(/^(?:[-*]\s*)?(?:\*\*)?([가-힣A-Za-z0-9\s]+?)(?:\*\*)?\s*:\s*(.*)$/);
      if (m) {
        const keyRaw = m[1].replace(/\s+/g, "").toLowerCase();
        const val = m[2].trim();
        let mapped = null;
        if (["가수", "아티스트", "artist"].includes(keyRaw)) mapped = "artist";
        else if (["동의어", "가수동의어", "artistaliases"].includes(keyRaw)) mapped = "artistAliases";
        else if (["노래", "제목", "곡명", "title"].includes(keyRaw)) mapped = "title";
        else if (["노래동의어", "제목동의어", "titlealiases"].includes(keyRaw)) mapped = "titleAliases";
        else if (["연도", "발매연도", "발매", "year"].includes(keyRaw)) mapped = "year";
        else if (["키워드", "단어힌트", "힌트", "keyword"].includes(keyRaw)) mapped = "keywordHint";
        else if (["가사", "하이라이트가사", "lyrics"].includes(keyRaw)) mapped = "lyricsQuestion";
        else if (["비하인드", "문제", "설명", "사연", "behind"].includes(keyRaw)) mapped = "behindQuestion";
        else if (["해설", "정답해설", "노트", "note"].includes(keyRaw)) mapped = "behindAnswerNote";
        else if (["하드모드", "hardmode", "hard"].includes(keyRaw)) mapped = "hardMode";

        if (mapped) {
          currentKey = mapped;
          fields[mapped] = fields[mapped] ? `${fields[mapped]}\n${val}` : val;
          return;
        }
      }

      if (currentKey && fields[currentKey] !== undefined) {
        fields[currentKey] = `${fields[currentKey]} ${line}`.trim();
      }
    });

    const artist = (fields.artist || "").trim();
    const title = (fields.title || "").trim();
    if (!artist || !title) return;

    const yearMatch = String(fields.year || "").match(/\d{4}/);
    const year = yearMatch ? Number(yearMatch[0]) : 2020;
    const decade = inferDecadeFromYear(year);

    const artistAliases = String(fields.artistAliases || "")
      .split(",")
      .map(s => s.trim())
      .filter(s => s && normalizeQuizText(s) !== normalizeQuizText(artist));

    const titleAliases = String(fields.titleAliases || "")
      .split(",")
      .map(s => s.trim())
      .filter(s => s && normalizeQuizText(s) !== normalizeQuizText(title));

    const keywordHint = (fields.keywordHint || `${year}년 히트곡, ${decade.replace("s", "년대")}`).trim();
    const lyricsQuestion = (fields.lyricsQuestion || "(등록된 하이라이트 가사 없음)").trim();
    const rawBehind = (fields.behindQuestion || `${year}년에 발표된 대표 히트곡입니다.`).trim();
    const maskedBehind = maskAnswerInBehindText(rawBehind, artist, artistAliases, title, titleAliases);
    const behindAnswerNote = (fields.behindAnswerNote || `${artist} '${title}'(${year}).`).trim();
    const explicitHard = /^(true|on|y|yes|ㅇ|예|포함)$/i.test(String(fields.hardMode || "").trim());
    const hardMode = explicitHard || HARD_MODE_ARTISTS.has(artist);

    const dupKey = `${normalizeQuizText(artist)}__${normalizeQuizText(title)}`;
    const existing = existingMap.get(dupKey);
    const slugId = `md_${decade}_${year}_${idx}_${Date.now().toString(36).slice(-4)}`;

    parsed.push({
      question: {
        id: existing ? existing.id : slugId,
        decade,
        year,
        artist,
        artistAliases,
        title,
        titleAliases,
        hardMode,
        behindQuestion: maskedBehind,
        behindAnswerNote,
        lyricsQuestion,
        keywordHint,
        itunesQuery: `${artist} ${title}`
      },
      isDuplicate: !!existing,
      rawBehind
    });
  });

  return parsed;
}

function formatQuestionsAsDataJsSnippet(questions) {
  return (questions || [])
    .map(q => JSON.stringify(q, null, 2))
    .join(",\n");
}

function _normalizeItunesMatchText(str) {
  return String(str || "")
    .replace(/[\u00C0-\u024F]/g, ch => ch.normalize("NFD").replace(/[\u0300-\u036f]/g, ""))
    .toLowerCase()
    .replace(/[\s\.\,\!\?\-\_\~\'\"\(\)\[\]\{\}\:\;\/\\&·•]/g, "");
}

function _buildItunesSearchQueries(qOrQuery) {
  if (typeof qOrQuery === "string" || !qOrQuery || !qOrQuery.title) {
    const raw = String(qOrQuery || "").trim();
    return raw ? [raw] : [];
  }
  const candidates = [];
  const pushUnique = s => {
    const clean = String(s || "").trim();
    if (clean && !candidates.some(x => x.toLowerCase() === clean.toLowerCase())) {
      candidates.push(clean);
    }
  };

  pushUnique(qOrQuery.itunesQuery);
  pushUnique(`${qOrQuery.artist || ""} ${qOrQuery.title || ""}`);

  const spacedKoreanAlias = (qOrQuery.artistAliases || []).find(a => /\s/.test(a) && /[가-힣]/.test(a));
  if (spacedKoreanAlias) {
    pushUnique(`${spacedKoreanAlias} ${qOrQuery.title || ""}`);
  }
  const asciiArtist = [qOrQuery.artist, ...(qOrQuery.artistAliases || [])].find(a => /^[A-Za-z0-9.\s'&-]+$/.test(String(a || "").trim()));
  const asciiTitle = [qOrQuery.title, ...(qOrQuery.titleAliases || [])].find(t => /^[A-Za-z0-9.\s'&-]+$/.test(String(t || "").trim()));
  if (asciiArtist && qOrQuery.title) {
    pushUnique(`${asciiArtist} ${qOrQuery.title}`);
  }
  if (asciiArtist && asciiTitle) {
    pushUnique(`${asciiArtist} ${asciiTitle}`);
  }
  return candidates.slice(0, 4);
}

function _scoreItunesTrackCandidate(track, qObj) {
  if (!track || !track.previewUrl) return -999;

  const rawTrack = String(track.trackName || "").toLowerCase();
  const rawArtist = String(track.artistName || "").toLowerCase();
  const rawAlbum = String(track.collectionName || "").toLowerCase();
  const combinedRaw = `${rawTrack} ${rawAlbum} ${rawArtist}`;

  const isJunk =
    /\b(mr|inst|instrumental|karaoke|tribute|cover|piano version|music box|lo-?fi|acoustic cover|8-bit|ringtone)\b/i.test(combinedRaw) ||
    /(반주|노래방|연주곡|mr|커버|뮤직박스|오르골|가라오케)/i.test(combinedRaw);

  if (!qObj || typeof qObj === "string" || !qObj.title) {
    return isJunk ? 10 : 100;
  }
  if (isJunk) return -150;

  const normArtist = _normalizeItunesMatchText(track.artistName);
  const baseArtist = _normalizeItunesMatchText(String(track.artistName || "").replace(/\([^)]*\)|\[[^\]]*\]|feat\..*|ft\..*/gi, ""));
  const normTrack = _normalizeItunesMatchText(track.trackName);
  const baseTrack = _normalizeItunesMatchText(String(track.trackName || "").replace(/\([^)]*\)|\[[^\]]*\]/g, ""));

  const artistTerms = [qObj.artist, ...(qObj.artistAliases || [])]
    .map(_normalizeItunesMatchText)
    .filter(Boolean);
  const titleTerms = [qObj.title, ...(qObj.titleAliases || [])]
    .map(_normalizeItunesMatchText)
    .filter(Boolean);

  let artistScore = 0;
  for (const a of artistTerms) {
    if (normArtist === a || baseArtist === a) {
      artistScore = Math.max(artistScore, 80);
    } else if (a.length >= 2 && (normArtist.includes(a) || a.includes(normArtist) || baseArtist.includes(a) || a.includes(baseArtist))) {
      artistScore = Math.max(artistScore, 55);
    }
  }

  let titleScore = 0;
  for (const t of titleTerms) {
    if (normTrack === t || baseTrack === t) {
      titleScore = Math.max(titleScore, 70);
    } else if (t.length >= 2 && (normTrack.includes(t) || baseTrack.includes(t) || t.includes(baseTrack))) {
      titleScore = Math.max(titleScore, 45);
    }
  }

  let total = artistScore + titleScore;
  if (artistTerms.length > 0 && artistScore === 0) total -= 25;
  if (titleTerms.length > 0 && titleScore === 0) total -= 25;

  if (/\b(live|concert|remix)\b/i.test(combinedRaw) || /(라이브|콘서트|실황|리믹스)/i.test(combinedRaw)) {
    total -= 15;
  }
  return total;
}

async function fetchItunesSongMeta(qOrQuery) {
  const queries = _buildItunesSearchQueries(qOrQuery);
  if (queries.length === 0) return { previewUrl: null, artworkUrl: "" };

  const isStructured = typeof qOrQuery === "object" && qOrQuery !== null && Boolean(qOrQuery.title);
  const minScore = isStructured ? 45 : 10;
  let best = null;
  let bestScore = -Infinity;
  let fallbackNonJunk = null;

  for (const rawQuery of queries) {
    const encoded = encodeURIComponent(rawQuery);
    const urls = [
      `https://itunes.apple.com/search?term=${encoded}&country=KR&entity=song&limit=15`,
      `https://itunes.apple.com/search?term=${encoded}&country=US&entity=song&limit=15`
    ];
    for (const url of urls) {
      try {
        const res = await fetch(url);
        if (!res.ok) continue;
        const data = await res.json();
        if (!data || !Array.isArray(data.results)) continue;
        for (const r of data.results) {
          const score = _scoreItunesTrackCandidate(r, qOrQuery);
          if (r && r.previewUrl && score > -100 && !fallbackNonJunk) {
            fallbackNonJunk = r;
          }
          if (score > bestScore) {
            bestScore = score;
            best = r;
          }
        }
        if (best && bestScore >= 110) {
          return {
            previewUrl: best.previewUrl,
            artworkUrl: (best.artworkUrl100 || "").replace("100x100bb", "300x300bb"),
            trackName: best.trackName,
            artistName: best.artistName
          };
        }
      } catch (err) {}
    }
  }

  const chosen = (best && best.previewUrl && bestScore >= minScore) ? best : fallbackNonJunk;
  if (chosen && chosen.previewUrl) {
    return {
      previewUrl: chosen.previewUrl,
      artworkUrl: (chosen.artworkUrl100 || "").replace("100x100bb", "300x300bb"),
      trackName: chosen.trackName,
      artistName: chosen.artistName
    };
  }

  return { previewUrl: null, artworkUrl: "" };
}

// ============================================================================
// [V2.0 하이브리드 방식 3] 원격 문제 DB 로드 (questions.json + 폴백 내장 DB)
// ============================================================================
window.__remoteQuestionsLoaded = false;
window.loadRemoteQuestionsDb = async function () {
  if (window.__remoteQuestionsLoaded) return QUESTIONS_DB;
  const candidates = [
    "./questions.json?t=" + Date.now(),
    "https://dg1682-commits.github.io/MUSICKING/questions.json?t=" + Date.now()
  ];
  for (const url of candidates) {
    try {
      const res = await fetch(url, { cache: "no-store" });
      if (!res.ok) continue;
      const data = await res.json();
      if (Array.isArray(data) && data.length > 0) {
        const byId = new Map(QUESTIONS_DB.map(q => [q.id, q]));
        data.forEach(q => {
          if (q && q.id && q.artist && q.title) {
            byId.set(q.id, q);
          }
        });
        QUESTIONS_DB = Array.from(byId.values());
        window.__remoteQuestionsLoaded = true;
        break;
      }
    } catch (e) {}
  }
  return QUESTIONS_DB;
};






